def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Exemplar motif offsets relative to its central 5; background 4 is transparent.
    stamp = {(-1, 0): 5, (-1, 1): 5,
             (0, -1): 8, (0, 0): 5, (0, 1): 8,
             (1, -1): 8, (1, 0): 5, (1, 1): 0}
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1:
                for (dr, dc), value in stamp.items():
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = value
    return out

